	 */
	async countActiveAccessTokensByGrant(
		grants: Array<{ clientId: string; userId: string }>,
	): Promise<Map<string, number>> {
		const counts = new Map<string, number>();
		if (grants.length === 0) return counts;

		const wanted = new Set(grants.map((grant) => grantKey(grant.clientId, grant.userId)));
		const rows = await this.accessTokenRepository.findForGrants(
			[...new Set(grants.map((grant) => grant.clientId))],
			[...new Set(grants.map((grant) => grant.userId))],
		);

		const nowSeconds = Math.floor(Date.now() / 1000);
		for (const row of rows) {
			const key = grantKey(row.clientId, row.userId);
			if (!wanted.has(key)) continue;
			const exp = this.jwtService.decodeUnverified<{ exp?: unknown } | null>(row.token)?.exp;
			if (typeof exp !== 'number' || exp <= nowSeconds) continue;
			counts.set(key, (counts.get(key) ?? 0) + 1);
		}
		return counts;
	}

